final class RVAZ_Wonen {
 const TYPE='rvaz_woning', ROLE='rvaz_makelaar', NS='rvaz-wonen/v1';
 static function init(){
  add_action('init',[__CLASS__,'register']); add_action('admin_init',[__CLASS__,'maybe_upgrade']); add_action('admin_notices',[__CLASS__,'page_notice']); add_action('rest_api_init',[__CLASS__,'rest']);
  add_action('add_meta_boxes',[__CLASS__,'boxes']); add_action('save_post_'.self::TYPE,[__CLASS__,'save']);
  add_action('admin_menu',[__CLASS__,'admin_menu']); add_action('admin_post_rvaz_wonen_apply',[__CLASS__,'apply']);
  add_action('admin_post_rvaz_wonen_save_office',[__CLASS__,'save_office']); add_action('admin_post_rvaz_wonen_wizard',[__CLASS__,'wizard_save']); add_action('admin_post_rvaz_wonen_change_plan',[__CLASS__,'change_plan']); add_action('admin_post_rvaz_wonen_save_settings',[__CLASS__,'save_settings']); add_action('wp_ajax_nopriv_rvaz_wonen_event',[__CLASS__,'track_event']); add_action('wp_ajax_rvaz_wonen_event',[__CLASS__,'track_event']); add_action('admin_post_rvaz_wonen_application_decision',[__CLASS__,'application_decision']); add_action('admin_post_nopriv_rvaz_wonen_verify_agent',[__CLASS__,'verify_agent']); add_action('admin_post_rvaz_wonen_verify_agent',[__CLASS__,'verify_agent']); add_action('admin_post_rvaz_wonen_agent_manage',[__CLASS__,'agent_manage']); add_action('admin_post_rvaz_wonen_invoice_manage',[__CLASS__,'invoice_manage']); add_action('admin_post_rvaz_wonen_subscription_manage',[__CLASS__,'subscription_manage']); add_action('admin_post_rvaz_wonen_message_manage',[__CLASS__,'message_manage']); add_action('admin_post_rvaz_wonen_invoice_pdf',[__CLASS__,'invoice_pdf']); add_action('admin_post_rvaz_wonen_cancel_subscription',[__CLASS__,'cancel_subscription']); add_action('admin_post_rvaz_wonen_request_news_promo',[__CLASS__,'request_news_promo']); add_action('admin_post_rvaz_wonen_save_billing',[__CLASS__,'save_billing']); add_action('rvaz_wonen_daily_billing',[__CLASS__,'daily_billing']); add_filter('the_content',[__CLASS__,'property_content'],20); add_action('wp',[__CLASS__,'count_property_view']); add_action('admin_post_nopriv_rvaz_wonen_contact',[__CLASS__,'contact']); add_action('admin_post_rvaz_wonen_contact',[__CLASS__,'contact']);
  add_shortcode('rvaz_wonen',[__CLASS__,'public_view']); add_shortcode('rvaz_wonen_portal',[__CLASS__,'portal']); add_shortcode('rvaz_wonen_agents',[__CLASS__,'agents_page']); add_shortcode('rvaz_wonen_pricing',[__CLASS__,'pricing_page']); add_action('admin_post_rvaz_wonen_save_pricing',[__CLASS__,'save_pricing']);
 
 }

 static function blocked($uid=0){$uid=$uid?:get_current_user_id();return $uid && get_user_meta($uid,'rvaz_wonen_blocked',true)==='1';}
 static function require_agent_access(){if(!is_user_logged_in()||self::blocked())wp_die('Je RVAZ Wonen-account is geblokkeerd. Neem contact op met RVAZ.');}
 static function page_notice(){
  if(!current_user_can('manage_options')) return;
  $missing=[];
  foreach(['wonen','wonen-voor-makelaars','wonen-tarieven','mijn-wonen'] as $slug) if(!get_page_by_path($slug,OBJECT,'page')) $missing[]=$slug;
  if($missing) echo '<div class="notice notice-error"><p><strong>RVAZ Wonen:</strong> pagina-aanmaak mislukt voor: '.esc_html(implode(', ',$missing)).'.</p></div>';
 }
 static function maybe_upgrade(){
  $version='1.0.1';
  if(get_option('rvaz_wonen_version')!==$version){
   self::install();
   self::ensure_pages();
   global $wpdb;
   $wpdb->query("UPDATE {$wpdb->prefix}rvaz_wonen_invoices SET invoice_no=REPLACE(invoice_no,'WONEN-','RVAZ-') WHERE invoice_no LIKE 'WONEN-%'");
   $wpdb->query("UPDATE {$wpdb->prefix}rvaz_wonen_invoices SET vat=0,total=subtotal"); foreach($wpdb->get_results("SELECT * FROM {$wpdb->prefix}rvaz_wonen_subscriptions") as $sub){$start=$sub->start_date?:current_time('Y-m-d');$wpdb->update($wpdb->prefix.'rvaz_wonen_subscriptions',['end_date'=>date('Y-m-d',strtotime($start.' +1 month -1 day')),'next_invoice_date'=>date('Y-m-d',strtotime($start.' +1 month'))],['id'=>$sub->id]);} if(!wp_next_scheduled('rvaz_wonen_daily_billing'))wp_schedule_event(time()+300,'daily','rvaz_wonen_daily_billing');
   update_option('rvaz_wonen_version',$version);
   flush_rewrite_rules(false);
  }
 }

 static function activate(){
  add_role(self::ROLE,'RVAZ Makelaar',['read'=>true,'upload_files'=>true,'edit_rvaz_woningen'=>true]);
  self::register(); self::install(); self::ensure_pages(); update_option('rvaz_wonen_version','1.0.1'); if(!wp_next_scheduled('rvaz_wonen_daily_billing'))wp_schedule_event(time()+300,'daily','rvaz_wonen_daily_billing'); flush_rewrite_rules();
 }
 static function install(){
  global $wpdb;$c=$wpdb->get_charset_collate();
  require_once ABSPATH.'wp-admin/includes/upgrade.php';
  dbDelta("CREATE TABLE {$wpdb->prefix}rvaz_wonen_applications(id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,office varchar(190) NOT NULL,plan varchar(20) NOT NULL DEFAULT '',contact_name varchar(190) NOT NULL DEFAULT '',phone varchar(60) NOT NULL DEFAULT '',status varchar(20) NOT NULL DEFAULT 'pending',created datetime NOT NULL,PRIMARY KEY(id)) $c;");
  dbDelta("CREATE TABLE {$wpdb->prefix}rvaz_wonen_subscriptions(id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,plan varchar(20) NOT NULL,status varchar(20) NOT NULL DEFAULT 'active',start_date date NULL,end_date date NULL,next_invoice_date date NULL,cancelled_date date NULL,PRIMARY KEY(id)) $c;");
  dbDelta("CREATE TABLE {$wpdb->prefix}rvaz_wonen_invoices(id bigint unsigned NOT NULL AUTO_INCREMENT,user_id bigint unsigned NOT NULL,invoice_no varchar(50) NOT NULL,period varchar(100) NOT NULL,subtotal decimal(10,2) NOT NULL,vat decimal(10,2) NOT NULL,total decimal(10,2) NOT NULL,status varchar(20) NOT NULL DEFAULT 'open',invoice_date date NULL,due_date date NULL,tikkie_url text NULL,pdf_url text NULL,paid_date date NULL,PRIMARY KEY(id),UNIQUE KEY invoice_no(invoice_no)) $c;");
  dbDelta("CREATE TABLE {$wpdb->prefix}rvaz_wonen_messages(id bigint unsigned NOT NULL AUTO_INCREMENT,property_id bigint unsigned NOT NULL,agent_user_id bigint unsigned NOT NULL,name varchar(190) NOT NULL,email varchar(190) NOT NULL,phone varchar(60) NOT NULL DEFAULT '',message text NOT NULL,status varchar(20) NOT NULL DEFAULT 'new',created datetime NOT NULL,PRIMARY KEY(id),KEY agent_user_id(agent_user_id),KEY property_id(property_id)) $c;");
 }
 static function ensure_pages(){
  $pages=[
   ['slug'=>'wonen','title'=>'Wonen','content'=>'[rvaz_wonen]'],
   ['slug'=>'wonen-voor-makelaars','title'=>'Wonen voor makelaars','content'=>'[rvaz_wonen_agents]'],
   ['slug'=>'wonen-tarieven','title'=>'Abonnementen & tarieven','content'=>'[rvaz_wonen_pricing]'],
   ['slug'=>'mijn-wonen','title'=>'Mijn Wonen','content'=>'[rvaz_wonen_portal]']
  ];
  foreach($pages as $p){
   $existing=get_page_by_path($p['slug'],OBJECT,'page');
   if(!$existing){
    wp_insert_post(['post_type'=>'page','post_status'=>'publish','post_title'=>$p['title'],'post_name'=>$p['slug'],'post_content'=>$p['content']]);
   } elseif(trim((string)$existing->post_content)===''){
    wp_update_post(['ID'=>$existing->ID,'post_content'=>$p['content']]);
   }
  }
  // Verwijder uitsluitend de door oudere RVAZ Wonen-versies aangemaakte child-pages.
  $wonen=get_page_by_path('wonen',OBJECT,'page');
  if($wonen){
   foreach(['makelaars'=>'[rvaz_wonen_agents]','tarieven'=>'[rvaz_wonen_pricing]'] as $slug=>$shortcode){
    $old=get_page_by_path('wonen/'.$slug,OBJECT,'page');
    if($old && (int)$old->post_parent===(int)$wonen->ID && trim((string)$old->post_content)===$shortcode){
     wp_trash_post($old->ID);
    }
   }
  }
 }
 static function register(){
  register_post_type(self::TYPE,['labels'=>['name'=>'RVAZ Wonen','singular_name'=>'Woning','add_new_item'=>'Nieuwe woning'],'public'=>true,'show_in_rest'=>true,'has_archive'=>false,'rewrite'=>['slug'=>'woning','with_front'=>false],'show_in_menu'=>'rvaz-wonen','menu_icon'=>'dashicons-admin-home','supports'=>['title','editor','thumbnail','author']]);
  register_taxonomy('rvaz_wonen_category',self::TYPE,['labels'=>['name'=>'Woningcategorieën'],'public'=>true,'show_in_rest'=>true,'hierarchical'=>true]);
 }
 static function boxes(){add_meta_box('rvaz_wonen_details','Woninggegevens',[__CLASS__,'box'],self::TYPE,'normal','high');}
 static function box($p){
  wp_nonce_field('rvaz_wonen_save','rvaz_wonen_nonce');
  $f=['adres'=>'Adres','postcode'=>'Postcode','plaats'=>'Plaats','prijs'=>'Prijs','woningtype'=>'Woningtype','status'=>'Status','slaapkamers'=>'Slaapkamers','woonoppervlak'=>'Woonoppervlak (m²)','perceel'=>'Perceel (m²)','energielabel'=>'Energielabel','makelaar_url'=>'Link naar makelaar'];
  echo '<div class="rvaz-admin-grid">';foreach($f as $k=>$l){$v=get_post_meta($p->ID,'_rvaz_wonen_'.$k,true);echo '<label><b>'.esc_html($l).'</b><input name="rvaz_wonen_'.esc_attr($k).'" value="'.esc_attr($v).'"></label>';}echo '</div><style>.rvaz-admin-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.rvaz-admin-grid input{width:100%;margin-top:5px}</style>';
 }
 static function save($id){
  if(self::blocked())return;
  if(!isset($_POST['rvaz_wonen_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['rvaz_wonen_nonce'])),'rvaz_wonen_save')||!current_user_can('edit_post',$id)||wp_is_post_autosave($id)||wp_is_post_revision($id))return;
  foreach(['adres','postcode','plaats','prijs','prijstype','borg','contractduur','aanvaarding','inkomenseisen','woningtype','transactie','status','bouwjaar','kamers','slaapkamers','badkamers','woonoppervlak','perceel','energielabel','tuin','balkon','garage','makelaar_url','views','contact_clicks','agent_clicks'] as $k) if(isset($_POST['rvaz_wonen_'.$k])) update_post_meta($id,'_rvaz_wonen_'.$k,sanitize_text_field(wp_unslash($_POST['rvaz_wonen_'.$k])));
 }
 static function fields($id){$a=['id'=>$id,'title'=>get_the_title($id),'description'=>wpautop(wp_kses_post(get_post_field('post_content',$id))),'url'=>get_permalink($id),'image'=>get_the_post_thumbnail_url($id,'large')?:''];foreach(['adres','postcode','plaats','prijs','prijstype','borg','contractduur','aanvaarding','inkomenseisen','woningtype','transactie','status','bouwjaar','kamers','slaapkamers','badkamers','woonoppervlak','perceel','energielabel','tuin','balkon','garage','makelaar_url','views','contact_clicks','agent_clicks'] as $k)$a[$k]=get_post_meta($id,'_rvaz_wonen_'.$k,true);return $a;}
