 static function public_view(){
  $s=isset($_GET['wonen_zoeken'])?sanitize_text_field(wp_unslash($_GET['wonen_zoeken'])):'';
  $type=isset($_GET['wonen_type'])?sanitize_text_field(wp_unslash($_GET['wonen_type'])):'';
  $woningtype=isset($_GET['wonen_woningtype'])?sanitize_text_field(wp_unslash($_GET['wonen_woningtype'])):'';
  $a=['post_type'=>self::TYPE,'post_status'=>'publish','posts_per_page'=>12];if($s)$a['s']=$s;$mq=[];if($type)$mq[]=['key'=>'_rvaz_wonen_transactie','value'=>$type];if($woningtype)$mq[]=['key'=>'_rvaz_wonen_woningtype','value'=>$woningtype];if($mq)$a['meta_query']=$mq;$q=new WP_Query($a);
  ob_start();echo self::css();?>
  <div class="rvw rvw-public"><section class="rvw-market-hero"><h1>Wonen op Voorne</h1><p>Koop- en huurwoningen, nieuwbouw en bedrijfspanden op Voorne aan Zee.</p><form class="rvw-market-search" method="get"><input name="wonen_zoeken" value="<?php echo esc_attr($s)?>" placeholder="Plaats, straat of postcode"><select name="wonen_type"><option value="">Koop & huur</option><option value="Koop" <?php selected($type,'Koop')?>>Koop</option><option value="Huur" <?php selected($type,'Huur')?>>Huur</option></select><select name="wonen_woningtype"><option value="">Alle woningtypen</option><option value="Woning" <?php selected($woningtype,'Woning')?>>Woning</option><option value="Appartement" <?php selected($woningtype,'Appartement')?>>Appartement</option><option value="Nieuwbouw" <?php selected($woningtype,'Nieuwbouw')?>>Nieuwbouw</option><option value="Bedrijfspand" <?php selected($woningtype,'Bedrijfspand')?>>Bedrijfspand</option></select><button class="rvw-btn">Zoeken</button></form></section>
  <nav class="rvw-market-tabs"><a class="rvw-market-tab <?php echo (!$type&&!$woningtype)?'active':''?>" href="?">Alle</a><a class="rvw-market-tab <?php echo $type==='Koop'?'active':''?>" href="?wonen_type=Koop">Koop</a><a class="rvw-market-tab <?php echo $type==='Huur'?'active':''?>" href="?wonen_type=Huur">Huur</a><a class="rvw-market-tab <?php echo $woningtype==='Nieuwbouw'?'active':''?>" href="?wonen_woningtype=Nieuwbouw">Nieuwbouw</a><a class="rvw-market-tab <?php echo $woningtype==='Bedrijfspand'?'active':''?>" href="?wonen_woningtype=Bedrijfspand">Bedrijfspanden</a></nav>
  <div class="rvw-results-head"><h2>Woningen</h2><span class="rvw-results-count"><?php echo (int)$q->found_posts?> resultaat<?php echo (int)$q->found_posts===1?'':'en'?></span></div><div class="rvw-list"><?php if(!$q->have_posts())echo '<div class="rvw-empty">Geen woningen gevonden. Probeer een andere zoekopdracht.</div>';while($q->have_posts()):$q->the_post();$d=self::fields(get_the_ID());$address=trim((string)$d['adres'])?:get_the_title();$location=trim($d['postcode'].' '.$d['plaats']);?><article class="rvw-listing"><a href="<?php the_permalink()?>"><div class="rvw-listing-photo"><?php if($d['image']):?><img src="<?php echo esc_url($d['image'])?>" alt="<?php echo esc_attr($address)?>"><?php else:?><div class="rvw-listing-placeholder">Geen foto beschikbaar</div><?php endif?><?php if(!empty($d['status'])):?><span class="rvw-listing-status"><?php echo esc_html($d['status'])?></span><?php endif?></div><div class="rvw-listing-body"><h3 class="rvw-listing-address"><?php echo esc_html($address)?></h3><div class="rvw-listing-place"><?php echo esc_html($location)?></div><div class="rvw-listing-price"><?php echo esc_html(self::price_label($d))?></div><div class="rvw-listing-features"><?php if($d['woonoppervlak']!==''):?><span class="rvw-listing-feature"><strong><?php echo esc_html($d['woonoppervlak'])?> m²</strong> wonen</span><?php endif?><?php if($d['kamers']!==''):?><span class="rvw-listing-feature"><strong><?php echo esc_html($d['kamers'])?></strong> kamers</span><?php elseif($d['slaapkamers']!==''):?><span class="rvw-listing-feature"><strong><?php echo esc_html($d['slaapkamers'])?></strong> slaapkamers</span><?php endif?><?php if($d['perceel']!==''):?><span class="rvw-listing-feature"><strong><?php echo esc_html($d['perceel'])?> m²</strong> perceel</span><?php endif?><?php if($d['energielabel']!==''):?><span class="rvw-listing-feature">Label <strong><?php echo esc_html($d['energielabel'])?></strong></span><?php endif?></div></div></a></article><?php endwhile;wp_reset_postdata()?></div></div>
  <?php return ob_get_clean();
 }
 static function portal_nav($page){$items=['dashboard'=>'Dashboard','woningen'=>'Mijn woningen','nieuw'=>'Nieuwe woning','kantoor'=>'Mijn kantoor','statistieken'=>'Statistieken','abonnement'=>'Abonnement','facturen'=>'Facturen','berichten'=>'Berichten','instellingen'=>'Instellingen'];echo '<aside class="rvw-side"><h2>Mijn Wonen</h2>';foreach($items as $k=>$v)echo '<a class="'.($page===$k?'active':'').'" href="?wonen_portal='.esc_attr($k).'">'.esc_html($v).'</a>';echo '</aside>';}
 static function portal(){
  if(!is_user_logged_in())return self::css().'<div class="rvw"><div class="rvw-panel"><h2>Makelaarsportaal</h2><p>Log in met je bestaande RVAZ-account om Mijn Wonen te gebruiken.</p><a class="rvw-btn" href="'.esc_url(wp_login_url(home_url(wp_unslash($_SERVER['REQUEST_URI']??'/mijn-wonen/')))).'">Inloggen</a></div></div>';
  $p=isset($_GET['wonen_portal'])?sanitize_key($_GET['wonen_portal']):'dashboard';$u=wp_get_current_user();if(self::blocked($u->ID))return self::css().'<div class="rvw"><div class="rvw-panel"><h2>RVAZ Wonen geblokkeerd</h2><p>Je makelaarstoegang is door RVAZ geblokkeerd. Je kunt geen woningen, berichten, abonnementen of facturen beheren.</p></div></div>';$is=in_array(self::ROLE,(array)$u->roles,true)||current_user_can('manage_options');
  ob_start();echo self::css();echo '<div class="rvw"><div class="rvw-layout">';self::portal_nav($p);echo '<main>';
  if(!$is){self::application_screen();echo '</main></div></div>';return ob_get_clean();}
  if($p==='woningen')self::my_properties($u->ID);elseif($p==='nieuw')self::wizard();elseif($p==='kantoor')self::office($u->ID);elseif($p==='statistieken')self::stats($u->ID);elseif($p==='abonnement')self::subscription($u->ID);elseif($p==='facturen')self::invoices($u->ID);elseif($p==='berichten')self::messages($u->ID);elseif($p==='instellingen')self::settings($u->ID);else self::dashboard($u->ID);
  echo '</main></div></div>';return ob_get_clean();
 }
 static function application_screen(){
  global $wpdb;$uid=get_current_user_id();$prices=self::prices();
  $requested=sanitize_key($_GET['pakket']??'');
  if(!in_array($requested,['basis','plus','pro'],true) || empty($prices[$requested]['enabled']))$requested='';
  $row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rvaz_wonen_applications WHERE user_id=%d ORDER BY id DESC LIMIT 1",$uid));
  echo '<div class="rvw-panel"><h1>Makelaarsabonnement aanvragen</h1>';
  if(isset($_GET['aanvraag'])&&$_GET['aanvraag']==='ontvangen')echo '<div class="rvw-empty"><strong>Aanvraag ontvangen.</strong><br>Je aanvraag staat klaar voor beoordeling door RVAZ.</div>';
  if($row && $row->status==='pending'){
   $plan=$row->plan??'';$label=isset($prices[$plan])?$prices[$plan]['name']:$plan;
   echo '<p>Aanvraagstatus: <span class="rvw-badge">In behandeling</span></p>';
   if($label)echo '<p>Gekozen abonnement: <strong>'.esc_html($label).'</strong></p>';
   echo '<p>Na goedkeuring wordt je makelaarsaccount geactiveerd.</p></div>';return;
  }
  echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rvaz_wonen_apply">'.wp_nonce_field('rvaz_wonen_apply','nonce',true,false);
  echo '<div class="rvw-formgrid"><label>Abonnement<select name="plan" required>';
  foreach(['basis','plus','pro'] as $k){$x=$prices[$k];if(empty($x['enabled']))continue;echo '<option value="'.esc_attr($k).'" '.selected($requested,$k,false).'>'.esc_html($x['name']).' — €'.esc_html($x['price']).'/mnd</option>';}
  echo '</select></label><label>Kantoornaam<input name="office" required></label><label>Contactpersoon<input name="contact_name" value="'.esc_attr(wp_get_current_user()->display_name).'" required></label><label>Telefoon<input name="phone" type="tel" required></label></div>';
  echo '<p><small>Geen BTW van toepassing. De aanvraag wordt eerst door RVAZ beoordeeld; er wordt niet automatisch afgeschreven.</small></p><p><button class="rvw-btn">Abonnement aanvragen</button></p></form></div>';
 }
 static function apply(){
  if(!is_user_logged_in()||!wp_verify_nonce($_POST['nonce']??'','rvaz_wonen_apply'))wp_die('Niet toegestaan');
  global $wpdb;$uid=get_current_user_id();$plan=sanitize_key($_POST['plan']??'');$prices=self::prices();if(!in_array($plan,['basis','plus','pro'],true)||empty($prices[$plan]['enabled']))wp_die('Ongeldig abonnement');
  $office=sanitize_text_field($_POST['office']??'');$name=sanitize_text_field($_POST['contact_name']??'');$phone=sanitize_text_field($_POST['phone']??'');if($office===''||$name===''||$phone==='')wp_die('Vul alle verplichte velden in.');
  $pending=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}rvaz_wonen_applications WHERE user_id=%d AND status IN ('email_pending','pending') LIMIT 1",$uid));
  if(!$pending){$wpdb->insert($wpdb->prefix.'rvaz_wonen_applications',['user_id'=>$uid,'office'=>$office,'plan'=>$plan,'contact_name'=>$name,'phone'=>$phone,'status'=>'email_pending','created'=>current_time('mysql')]);$pending=$wpdb->insert_id;}
  $token=wp_generate_password(32,false,false);update_user_meta($uid,'rvaz_wonen_verify_token',wp_hash_password($token));$u=get_userdata($uid);$url=add_query_arg(['action'=>'rvaz_wonen_verify_agent','uid'=>$uid,'app'=>(int)$pending,'token'=>$token],admin_url('admin-post.php'));wp_mail($u->user_email,'Bevestig je RVAZ Wonen makelaarsaanvraag',"Bevestig je e-mailadres:\n$url\n\nDaarna moet RVAZ je aanvraag nog goedkeuren.");
  wp_safe_redirect(add_query_arg('aanvraag','verificatie',home_url('/mijn-wonen/')));exit;
 }
 static function dashboard($uid){$q=new WP_Query(['post_type'=>self::TYPE,'author'=>$uid,'post_status'=>['publish','draft'],'posts_per_page'=>-1]);$active=0;$draft=0;foreach($q->posts as $x){if($x->post_status==='publish')$active++;else$draft++;}echo '<div class="rvw-panel"><h1>Dashboard</h1><p>Welkom in Mijn Wonen.</p><div class="rvw-stats"><div class="rvw-stat"><strong>'.$active.'</strong>Actief</div><div class="rvw-stat"><strong>0</strong>Verkocht</div><div class="rvw-stat"><strong>'.$draft.'</strong>Concept</div><div class="rvw-stat"><strong>0</strong>Weergaven</div></div></div><div class="rvw-panel"><h2>Laatste woningen</h2>';self::properties_table($q->posts);echo '</div>';}
 static function price_label($d){$raw=trim((string)($d['prijs']??''));if($raw==='')return 'Prijs op aanvraag';$n=is_numeric(str_replace(',','.',$raw))?(float)str_replace(',','.',$raw):null;$price=$n!==null?'€ '.number_format($n,($n==floor($n)?0:2),',','.'):'€ '.$raw;if(strtolower((string)($d['transactie']??''))==='huur')$price.=' p/m';elseif(!empty($d['prijstype']))$price.=' '.$d['prijstype'];return $price;}
 static function properties_table($posts){if(!$posts){echo '<div class="rvw-empty">Nog geen woningen.</div>';return;}echo '<table class="rvw-table"><tr><th>Woning</th><th>Status</th><th>Prijs</th><th>Acties</th></tr>';foreach($posts as $x){$d=self::fields($x->ID);$edit=add_query_arg(['wonen_portal'=>'nieuw','stap'=>1,'woning_id'=>$x->ID],home_url('/mijn-wonen/'));$promo=get_post_meta($x->ID,'_rvaz_wonen_news_promo',true);echo '<tr><td>'.esc_html($x->post_title).'</td><td>'.esc_html($x->post_status).'</td><td>'.esc_html(self::price_label($d)).'</td><td><a href="'.esc_url($edit).'">Bewerken</a> · ';if($promo==='requested')echo '<span class="rvw-badge">Nieuwsbericht aangevraagd</span>';else echo '<form style="display:inline" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rvaz_wonen_request_news_promo"><input type="hidden" name="woning_id" value="'.$x->ID.'">'.wp_nonce_field('rvaz_wonen_news_promo_'.$x->ID,'nonce',true,false).'<button style="border:0;background:none;padding:0;color:#1688e8;cursor:pointer;text-decoration:underline">Promoot als nieuws (€29)</button></form>';echo '</td></tr>';}echo '</table>';}
 static function my_properties($uid){$q=get_posts(['post_type'=>self::TYPE,'author'=>$uid,'post_status'=>['publish','draft'],'numberposts'=>-1]);echo '<div class="rvw-panel"><h1>Mijn woningen</h1><p><a class="rvw-btn" href="?wonen_portal=nieuw">Nieuwe woning</a></p>';self::properties_table($q);echo '</div>';}
 static function wizard(){
  $uid=get_current_user_id();$step=max(1,min(5,(int)($_GET['stap']??1)));$id=absint($_GET['woning_id']??0);
  if($id && ((int)get_post_field('post_author',$id)!==$uid || get_post_type($id)!==self::TYPE))$id=0;
  $v=function($k)use($id){return $id?get_post_meta($id,'_rvaz_wonen_'.$k,true):'';};
  $names=['Basisgegevens','Kenmerken','Foto’s','Omschrijving','Publiceren'];
  echo '<div class="rvw-panel"><h1>'.($id?'Woning bijwerken':'Nieuwe woning').'</h1><div class="rvw-steps">';foreach($names as $i=>$n)echo '<div class="rvw-step '.(($i+1)===$step?'on':'').'">'.($i+1).'. '.esc_html($n).'</div>';echo '</div>';
  echo '<form method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rvaz_wonen_wizard"><input type="hidden" name="step" value="'.$step.'"><input type="hidden" name="woning_id" value="'.$id.'">'.wp_nonce_field('rvaz_wonen_wizard','nonce',true,false);
  if($step===1){
   echo '<div class="rvw-formgrid"><label>Adres<input name="adres" value="'.esc_attr($v('adres')).'" required></label><label>Postcode<input name="postcode" value="'.esc_attr($v('postcode')).'" required></label><label>Plaats<input name="plaats" value="'.esc_attr($v('plaats')).'" required></label><label>Woningtype<select name="woningtype">'.self::opts(['Woning','Appartement','Nieuwbouw','Bedrijfspand'],$v('woningtype')).'</select></label><label>Koop / huur<select name="transactie">'.self::opts(['Koop','Huur'],$v('transactie')).'</select></label><label>Status<select name="status">'.self::opts(['Beschikbaar','Onder bod','Verkocht','Verhuurd'],$v('status')).'</select></label><label>Prijs (€)<input type="number" step="0.01" min="0" name="prijs" value="'.esc_attr($v('prijs')).'" required></label><label>Prijsconditie (koop)<select name="prijstype">'.self::opts(['k.k.','v.o.n.','inclusief kosten koper','exclusief kosten koper','anders'],$v('prijstype')).'</select></label><label>Aanvaarding / beschikbaar per<input name="aanvaarding" value="'.esc_attr($v('aanvaarding')).'"></label><label>Bouwjaar<input type="number" name="bouwjaar" value="'.esc_attr($v('bouwjaar')).'"></label><label>Woonoppervlak m²<input type="number" name="woonoppervlak" value="'.esc_attr($v('woonoppervlak')).'"></label><label>Perceel m²<input type="number" name="perceel" value="'.esc_attr($v('perceel')).'"></label></div>';
  }elseif($step===2){
   echo '<div class="rvw-formgrid"><label>Kamers<input type="number" name="kamers" value="'.esc_attr($v('kamers')).'"></label><label>Slaapkamers<input type="number" name="slaapkamers" value="'.esc_attr($v('slaapkamers')).'"></label><label>Badkamers<input type="number" name="badkamers" value="'.esc_attr($v('badkamers')).'"></label><label>Energielabel<select name="energielabel">'.self::opts(['A++++','A+++','A++','A+','A','B','C','D','E','F','G'],$v('energielabel')).'</select></label><label>Tuin<select name="tuin">'.self::opts(['Nee','Ja'],$v('tuin')).'</select></label><label>Balkon<select name="balkon">'.self::opts(['Nee','Ja'],$v('balkon')).'</select></label><label>Garage<select name="garage">'.self::opts(['Nee','Ja'],$v('garage')).'</select></label><label>Borg (huur)<input name="borg" value="'.esc_attr($v('borg')).'" placeholder="Bijv. 1 maand huur"></label><label>Contractduur (huur)<input name="contractduur" value="'.esc_attr($v('contractduur')).'"></label><label style="grid-column:1/-1">Benodigde inkomensgegevens (huur)<textarea name="inkomenseisen" rows="4">'.esc_textarea($v('inkomenseisen')).'</textarea></label></div>';
  }elseif($step===3){
   $gallery=$id?(array)get_post_meta($id,'_rvaz_wonen_gallery',true):[];if($gallery){echo '<div class="rvw-photo-grid">';foreach($gallery as $aid){$url=wp_get_attachment_image_url((int)$aid,'medium');if($url)echo '<img src="'.esc_url($url).'" alt="">';}echo '</div>';}
   echo '<div class="rvw-empty"><h3>Foto’s toevoegen</h3><p>Kies meerdere foto’s tegelijk, of voeg later nog extra foto’s toe. Bestaande foto’s blijven bewaard. De eerste foto is de hoofdafbeelding.</p><input type="file" name="woning_fotos[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple></div>';
  }elseif($step===4){
   echo '<label>Titel<input name="woning_title" value="'.esc_attr($id?get_the_title($id):'').'" required></label><p><label>Omschrijving<textarea name="woning_description" rows="12" required>'.esc_textarea($id?get_post_field('post_content',$id):'').'</textarea></label></p>';
  }else{
   if(!$id){echo '<div class="rvw-empty">Vul eerst de eerdere stappen in.</div>';}else{$d=self::fields($id);echo '<div class="rvw-panel"><h2>'.esc_html(get_the_title($id)).'</h2><p><strong>'.esc_html($d['adres']).', '.esc_html($d['postcode']).' '.esc_html($d['plaats']).'</strong></p><p>'.esc_html($d['woningtype']).' · '.esc_html($d['transactie']).' · '.esc_html(self::price_label($d)).'</p><p>'.esc_html($d['slaapkamers']).' slaapkamers · '.esc_html($d['woonoppervlak']).' m² · energielabel '.esc_html($d['energielabel']).'</p></div>';}
  }
  if($step>1 && $id)echo '<a class="rvw-btn alt" href="?wonen_portal=nieuw&stap='.($step-1).'&woning_id='.$id.'">Vorige</a> ';
  if($step<5)echo '<button class="rvw-btn" name="wizard_action" value="next">Opslaan en volgende</button>';else echo '<button class="rvw-btn" name="wizard_action" value="publish">Woning publiceren</button>';
  echo '</form></div>';
 }
 static function opts($items,$current){$o='';foreach($items as $x)$o.='<option '.selected($current,$x,false).'>'.esc_html($x).'</option>';return $o;}
 static function wizard_save(){self::require_agent_access();
  if(!is_user_logged_in()||!wp_verify_nonce($_POST['nonce']??'','rvaz_wonen_wizard'))wp_die('Niet toegestaan');
  $uid=get_current_user_id();$u=wp_get_current_user();if(!in_array(self::ROLE,(array)$u->roles,true)&&!current_user_can('manage_options'))wp_die('Geen makelaarsaccount.');
  $step=max(1,min(5,absint($_POST['step']??1)));$id=absint($_POST['woning_id']??0);
  if($id && ((int)get_post_field('post_author',$id)!==$uid||get_post_type($id)!==self::TYPE))wp_die('Ongeldige woning.');
  if(!$id){$id=wp_insert_post(['post_type'=>self::TYPE,'post_status'=>'draft','post_author'=>$uid,'post_title'=>'Nieuwe woning']);if(is_wp_error($id)||!$id)wp_die('Kon concept niet aanmaken.');}
  $map=[1=>['adres','postcode','plaats','woningtype','transactie','status','prijs','prijstype','aanvaarding','bouwjaar','woonoppervlak','perceel'],2=>['kamers','slaapkamers','badkamers','energielabel','tuin','balkon','garage','borg','contractduur','inkomenseisen']];
  if(isset($map[$step]))foreach($map[$step] as $k)update_post_meta($id,'_rvaz_wonen_'.$k,sanitize_text_field(wp_unslash($_POST[$k]??'')));
  if($step===3&&!empty($_FILES['woning_fotos']['name'][0])){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$files=$_FILES['woning_fotos'];$ids=[];foreach($files['name'] as $i=>$name){if(!$name)continue;$_FILES['rvaz_one']=['name'=>$name,'type'=>$files['type'][$i],'tmp_name'=>$files['tmp_name'][$i],'error'=>$files['error'][$i],'size'=>$files['size'][$i]];$aid=media_handle_upload('rvaz_one',$id);if(!is_wp_error($aid))$ids[]=$aid;}if($ids){$existing=(array)get_post_meta($id,'_rvaz_wonen_gallery',true);$all=array_values(array_unique(array_merge(array_map('intval',$existing),array_map('intval',$ids))));update_post_meta($id,'_rvaz_wonen_gallery',$all);if(!has_post_thumbnail($id))set_post_thumbnail($id,$all[0]);}}
  if($step===4){$title=sanitize_text_field(wp_unslash($_POST['woning_title']??''));$desc=wp_kses_post(wp_unslash($_POST['woning_description']??''));wp_update_post(['ID'=>$id,'post_title'=>$title?:'Woning','post_content'=>$desc]);}
  if($step===5&&($_POST['wizard_action']??'')==='publish'){
   global $wpdb;$sub=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rvaz_wonen_subscriptions WHERE user_id=%d AND status='active' ORDER BY id DESC LIMIT 1",$uid));$prices=self::prices();
   if(!$sub||empty($prices[$sub->plan]))wp_die('Geen actief Wonen-abonnement.');
   $limit=(int)$prices[$sub->plan]['limit'];$published=(int)count_user_posts($uid,self::TYPE,true);if($limit>0&&$published>=$limit)wp_die('Je pakketlimiet is bereikt.');
   wp_update_post(['ID'=>$id,'post_status'=>'publish']);wp_safe_redirect(add_query_arg(['wonen_portal'=>'woningen','gepubliceerd'=>1],home_url('/mijn-wonen/')));exit;
  }
  wp_safe_redirect(add_query_arg(['wonen_portal'=>'nieuw','stap'=>min(5,$step+1),'woning_id'=>$id],home_url('/mijn-wonen/')));exit;
 }
