 static function stats($uid){$posts=get_posts(['post_type'=>self::TYPE,'author'=>$uid,'post_status'=>['publish','draft'],'numberposts'=>-1]);$v=$c=$a=0;foreach($posts as $p){$v+=(int)get_post_meta($p->ID,'_rvaz_wonen_views',true);$c+=(int)get_post_meta($p->ID,'_rvaz_wonen_contact_clicks',true);$a+=(int)get_post_meta($p->ID,'_rvaz_wonen_agent_clicks',true);}echo '<div class="rvw-panel"><h1>Statistieken</h1><div class="rvw-stats"><div class="rvw-stat"><strong>'.$v.'</strong>Woningweergaven</div><div class="rvw-stat"><strong>'.$c.'</strong>Contactklikken</div><div class="rvw-stat"><strong>'.$a.'</strong>Makelaar-klikken</div><div class="rvw-stat"><strong>—</strong>Favorieten</div></div><p><small>Favorieten worden pas getoond zodra de favorietenfunctie actief is; er worden geen fictieve cijfers weergegeven.</small></p></div>';}
