 static function change_plan(){self::require_agent_access();if(!is_user_logged_in()||!wp_verify_nonce($_POST['nonce']??'','rvaz_wonen_change_plan'))wp_die('Niet toegestaan');$plan=sanitize_key($_POST['plan']??'');$p=self::prices();if(!in_array($plan,['basis','plus','pro'],true)||empty($p[$plan]['enabled']))wp_die('Ongeldig pakket');global $wpdb;$uid=get_current_user_id();$id=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}rvaz_wonen_subscriptions WHERE user_id=%d AND status='active' ORDER BY id DESC LIMIT 1",$uid));$oldplan=$id?$wpdb->get_var($wpdb->prepare("SELECT plan FROM {$wpdb->prefix}rvaz_wonen_subscriptions WHERE id=%d",$id)):'';if($id)$wpdb->update($wpdb->prefix.'rvaz_wonen_subscriptions',['plan'=>$plan],['id'=>$id]);else $wpdb->insert($wpdb->prefix.'rvaz_wonen_subscriptions',['user_id'=>$uid,'plan'=>$plan,'status'=>'active','start_date'=>current_time('Y-m-d'),'end_date'=>date('Y-m-d',strtotime(current_time('Y-m-d').' +1 month -1 day')),'next_invoice_date'=>date('Y-m-d',strtotime(current_time('Y-m-d').' +1 month'))]);if($oldplan!==$plan)self::create_invoice($uid,$plan);wp_safe_redirect(add_query_arg(['wonen_portal'=>'abonnement','gewijzigd'=>1],home_url('/mijn-wonen/')));exit;}
