  global $post;if(!$post)return $content;$d=self::fields($post->ID);$gallery=(array)get_post_meta($post->ID,'_rvaz_wonen_gallery',true);$author=(int)$post->post_author;
  $office=get_user_meta($author,'rvaz_wonen_office_name',true);$phone=get_user_meta($author,'rvaz_wonen_phone',true);$website=get_user_meta($author,'rvaz_wonen_website',true);$address=trim((string)$d['adres'])?:get_the_title($post);$location=trim($d['postcode'].' '.$d['plaats']);
  $labels=['woningtype'=>'Soort woning','transactie'=>'Aanbod','status'=>'Status','bouwjaar'=>'Bouwjaar','woonoppervlak'=>'Woonoppervlakte','perceel'=>'Perceeloppervlakte','kamers'=>'Aantal kamers','slaapkamers'=>'Slaapkamers','badkamers'=>'Badkamers','energielabel'=>'Energielabel','tuin'=>'Tuin','balkon'=>'Balkon','garage'=>'Garage','aanvaarding'=>'Aanvaarding','borg'=>'Borg','contractduur'=>'Contractduur','inkomenseisen'=>'Inkomenseisen'];
  ob_start();echo self::css();echo '<div class="rvw rvw-public rvw-property"><div class="rvw-property-top"><div><h1>'.esc_html($address).'</h1><div class="rvw-property-location">'.esc_html($location).'</div></div><div class="rvw-property-price">'.esc_html(self::price_label($d)).'</div></div>';
  $photos=[];foreach($gallery as $aid){$url=wp_get_attachment_image_url((int)$aid,'large');$full=wp_get_attachment_url((int)$aid);if($url)$photos[]=['url'=>$url,'full'=>$full?:$url];}if(!$photos&&!empty($d['image']))$photos[]=['url'=>$d['image'],'full'=>$d['image']];if($photos){$show=array_slice($photos,0,3);echo '<div class="rvw-property-gallery '.(count($show)===1?'single':'').'">';foreach($show as $ph)echo '<a href="'.esc_url($ph['full']).'"><img src="'.esc_url($ph['url']).'" alt="'.esc_attr($address).'"></a>';echo '</div>';}
  echo '<div class="rvw-property-columns"><main class="rvw-property-main"><div class="rvw-keyfacts">';if($d['woonoppervlak']!=='')echo '<div class="rvw-keyfact"><strong>'.esc_html($d['woonoppervlak']).' m²</strong>wonen</div>';if($d['perceel']!=='')echo '<div class="rvw-keyfact"><strong>'.esc_html($d['perceel']).' m²</strong>perceel</div>';if($d['kamers']!=='')echo '<div class="rvw-keyfact"><strong>'.esc_html($d['kamers']).'</strong>kamers</div>';if($d['slaapkamers']!=='')echo '<div class="rvw-keyfact"><strong>'.esc_html($d['slaapkamers']).'</strong>slaapkamers</div>';if($d['energielabel']!=='')echo '<div class="rvw-keyfact"><strong>'.esc_html($d['energielabel']).'</strong>energielabel</div>';echo '</div><h2>Omschrijving</h2><div class="rvw-description">'.wpautop(wp_kses_post($post->post_content)).'</div><section class="rvw-specs"><h2>Kenmerken</h2>';
  foreach($labels as $k=>$label){$v=trim((string)($d[$k]??''));if($v==='')continue;if(in_array($k,['woonoppervlak','perceel'],true))$v.=' m²';echo '<div class="rvw-spec-row"><div class="rvw-spec-label">'.esc_html($label).'</div><div class="rvw-spec-value">'.esc_html($v).'</div></div>';}echo '</section></main>';
  echo '<aside class="rvw-agent-card"><h2>Interesse in deze woning?</h2><div class="rvw-agent-name">'.esc_html($office?:get_the_author_meta('display_name',$author)).'</div><div class="rvw-agent-meta">'.($phone?esc_html($phone):'Neem rechtstreeks contact op met de makelaar.').'</div>';
  if(isset($_GET['contact'])&&$_GET['contact']==='verzonden')echo '<div class="rvw-empty"><strong>Bericht verzonden.</strong><br>De makelaar heeft je aanvraag ontvangen.</div>';
  echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rvaz_wonen_contact"><input type="hidden" name="property_id" value="'.(int)$post->ID.'">'.wp_nonce_field('rvaz_wonen_contact_'.$post->ID,'nonce',true,false).'<label>Naam<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Telefoon<input name="phone" type="tel"></label><label>Bericht<textarea name="message" required placeholder="Ik heb interesse in deze woning..."></textarea></label><button class="rvw-btn">Neem contact op</button></form>';if($website)echo '<a class="rvw-agent-link" href="'.esc_url($website).'" target="_blank" rel="noopener">Bekijk website makelaar</a>';echo '</aside></div></div>';
  return ob_get_clean();
 }
 static function contact(){
  $id=absint($_POST['property_id']??0);if(!$id||get_post_type($id)!==self::TYPE||get_post_status($id)!=='publish')wp_die('Woning niet gevonden.');
  if(!wp_verify_nonce($_POST['nonce']??'','rvaz_wonen_contact_'.$id))wp_die('Niet toegestaan');
  $name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$phone=sanitize_text_field(wp_unslash($_POST['phone']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));
  if($name===''||!is_email($email)||$message==='')wp_die('Vul naam, geldig e-mailadres en bericht in.');
  global $wpdb;$agent=(int)get_post_field('post_author',$id);$wpdb->insert($wpdb->prefix.'rvaz_wonen_messages',['property_id'=>$id,'agent_user_id'=>$agent,'name'=>$name,'email'=>$email,'phone'=>$phone,'message'=>$message,'status'=>'new','created'=>current_time('mysql')]);
  $to=get_userdata($agent);if($to&&is_email($to->user_email))wp_mail($to->user_email,'Nieuwe reactie op woning: '.get_the_title($id),"Naam: $name\nE-mail: $email\nTelefoon: $phone\n\n$message\n\nWoning: ".get_permalink($id));
  $n=(int)get_post_meta($id,'_rvaz_wonen_contact_clicks',true);update_post_meta($id,'_rvaz_wonen_contact_clicks',$n+1);
  wp_safe_redirect(add_query_arg('contact','verzonden',get_permalink($id)));exit;
 }
