 static function verify_agent(){
  $uid=absint($_GET['uid']??0);$app=absint($_GET['app']??0);$token=(string)($_GET['token']??'');$hash=get_user_meta($uid,'rvaz_wonen_verify_token',true);if(!$uid||!$app||!$token||!$hash||!wp_check_password($token,$hash))wp_die('Deze verificatielink is ongeldig of verlopen.');
  global $wpdb;$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rvaz_wonen_applications WHERE id=%d AND user_id=%d",$app,$uid));if(!$row)wp_die('Aanvraag niet gevonden.');$wpdb->update($wpdb->prefix.'rvaz_wonen_applications',['status'=>'pending'],['id'=>$app]);delete_user_meta($uid,'rvaz_wonen_verify_token');update_user_meta($uid,'rvaz_wonen_email_verified',current_time('mysql'));wp_safe_redirect(add_query_arg('aanvraag','geverifieerd',home_url('/mijn-wonen/')));exit;
 }
 static function create_invoice($uid,$plan){
  global $wpdb;$p=self::prices();if(empty($p[$plan]))return false;$amount=round((float)$p[$plan]['price'],2);$date=current_time('Y-m-d');$due=date('Y-m-d',strtotime($date.' +14 days'));$seq=(int)get_option('rvaz_wonen_invoice_seq',0)+1;update_option('rvaz_wonen_invoice_seq',$seq);$no='RVAZ-'.date('Y').'-'.str_pad((string)$seq,4,'0',STR_PAD_LEFT);$sub=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rvaz_wonen_subscriptions WHERE user_id=%d AND status='active' ORDER BY id DESC LIMIT 1",$uid));$period=$sub&&$sub->start_date&&$sub->end_date?date_i18n('j F Y',strtotime($sub->start_date)).' t/m '.date_i18n('j F Y',strtotime($sub->end_date)):date_i18n('F Y');
  $wpdb->insert($wpdb->prefix.'rvaz_wonen_invoices',['user_id'=>$uid,'invoice_no'=>$no,'period'=>$period,'subtotal'=>$amount,'vat'=>0,'total'=>$amount,'status'=>'open','invoice_date'=>$date,'due_date'=>$due]);return $wpdb->insert_id;
 }
 static function agent_manage(){
  if(!current_user_can('manage_options'))wp_die('Niet toegestaan');$uid=absint($_POST['user_id']??0);if(!$uid||!wp_verify_nonce($_POST['nonce']??'','rvaz_wonen_agent_'.$uid))wp_die('Niet toegestaan');$do=sanitize_key($_POST['do']??'');$u=get_userdata($uid);if(!$u)wp_die('Account niet gevonden.');global $wpdb;
  if($do==='block'){update_user_meta($uid,'rvaz_wonen_blocked','1');$wpdb->update($wpdb->prefix.'rvaz_wonen_subscriptions',['status'=>'paused'],['user_id'=>$uid,'status'=>'active']);foreach(get_posts(['post_type'=>self::TYPE,'author'=>$uid,'post_status'=>['publish','pending','future'],'numberposts'=>-1,'fields'=>'ids']) as $pid)wp_update_post(['ID'=>$pid,'post_status'=>'draft']);}elseif($do==='unblock')delete_user_meta($uid,'rvaz_wonen_blocked');elseif($do==='limit')update_user_meta($uid,'rvaz_wonen_limit_override',max(0,absint($_POST['limit']??0)));elseif($do==='remove_wonen'){$u->remove_role(self::ROLE);update_user_meta($uid,'rvaz_wonen_blocked','1');$wpdb->update($wpdb->prefix.'rvaz_wonen_subscriptions',['status'=>'cancelled'],['user_id'=>$uid]);foreach(get_posts(['post_type'=>self::TYPE,'author'=>$uid,'post_status'=>'any','numberposts'=>-1,'fields'=>'ids']) as $pid)wp_update_post(['ID'=>$pid,'post_status'=>'draft']);}
  wp_safe_redirect(admin_url('admin.php?page=rvaz-wonen-makelaars'));exit;
 }
