 static function pdf_escape($v){$v=wp_strip_all_tags((string)$v);$v=str_replace(['\\','(',')',"\r","\n"],['\\\\','\\(','\\)',' ',' '],$v);return function_exists('iconv')?(iconv('UTF-8','Windows-1252//TRANSLIT',$v)?:$v):$v;}
 static function invoice_pdf(){
  if(!is_user_logged_in())wp_die('Niet toegestaan');$id=absint($_GET['invoice_id']??0);if(!$id||!wp_verify_nonce($_GET['nonce']??'','rvaz_wonen_invoice_pdf_'.$id))wp_die('Niet toegestaan');global $wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rvaz_wonen_invoices WHERE id=%d",$id));if(!$r||((int)$r->user_id!==get_current_user_id()&&!current_user_can('manage_options')))wp_die('Factuur niet gevonden.');$u=get_userdata((int)$r->user_id);$bill=self::billing();$office=get_user_meta((int)$r->user_id,'rvaz_wonen_office_name',true);$lines=['RVAZ Wonen','FACTUUR '.$r->invoice_no,'','Aan: '.($office?:$u->display_name),$u->user_email,'','Factuurdatum: '.$r->invoice_date,'Vervaldatum: '.$r->due_date,'Periode: '.$r->period,'','Abonnement RVAZ Wonen','Bedrag: EUR '.number_format((float)$r->total,2,',','.'),'BTW: niet van toepassing','Totaal: EUR '.number_format((float)$r->total,2,',','.'),'','Status: '.$r->status,'','IBAN: '.$bill['iban'],'Rekeninghouder: '.$bill['account_name'],$bill['address'],$bill['postcode_city'],$bill['email'],'',$bill['note']];
  $content="BT\n/F1 12 Tf\n50 790 Td\n";foreach($lines as $i=>$line){if($i)$content.="0 -24 Td\n";$content.="(".self::pdf_escape($line).") Tj\n";}$content.="ET";$objs=[];$objs[]="1 0 obj<< /Type /Catalog /Pages 2 0 R >>endobj";$objs[]="2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1 >>endobj";$objs[]="3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>endobj";$objs[]="4 0 obj<< /Length ".strlen($content)." >>stream\n$content\nendstream\nendobj";$objs[]="5 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>endobj";$pdf="%PDF-1.4\n";$offset=[0];foreach($objs as $o){$offset[]=strlen($pdf);$pdf.=$o."\n";}$xref=strlen($pdf);$pdf.="xref\n0 6\n0000000000 65535 f \n";for($i=1;$i<=5;$i++)$pdf.=sprintf("%010d 00000 n \n",$offset[$i]);$pdf.="trailer<< /Size 6 /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";nocache_headers();header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.sanitize_file_name($r->invoice_no).'.pdf"');header('Content-Length: '.strlen($pdf));echo $pdf;exit;
 }

