 static function admin_agents(){
  global $wpdb;$ids=[];foreach(get_users(['role'=>self::ROLE,'fields'=>'ID']) as $id)$ids[]=(int)$id;foreach($wpdb->get_col("SELECT DISTINCT user_id FROM {$wpdb->prefix}rvaz_wonen_subscriptions") as $id)$ids[]=(int)$id;foreach($wpdb->get_col("SELECT DISTINCT user_id FROM {$wpdb->prefix}rvaz_wonen_applications") as $id)$ids[]=(int)$id;foreach($wpdb->get_col($wpdb->prepare("SELECT DISTINCT post_author FROM {$wpdb->posts} WHERE post_type=%s AND post_author>0",self::TYPE)) as $id)$ids[]=(int)$id;$ids=array_values(array_unique(array_filter($ids)));$users=$ids?get_users(['include'=>$ids,'orderby'=>'display_name']):[];
  $b='<p>Beheer alleen Wonen-toegang; het gewone RVAZ-account blijft bestaan.</p><table class="widefat striped"><tr><th>Makelaar</th><th>Status</th><th>Woningen</th><th>Extra limiet</th><th>Acties</th></tr>';
  foreach($users as $u){$sub=$wpdb->get_row($wpdb->prepare("SELECT plan,status FROM {$wpdb->prefix}rvaz_wonen_subscriptions WHERE user_id=%d ORDER BY id DESC LIMIT 1",$u->ID));$app=$wpdb->get_row($wpdb->prepare("SELECT status FROM {$wpdb->prefix}rvaz_wonen_applications WHERE user_id=%d ORDER BY id DESC LIMIT 1",$u->ID));$blocked=get_user_meta($u->ID,'rvaz_wonen_blocked',true)==='1';$limit=get_user_meta($u->ID,'rvaz_wonen_limit_override',true);$status=$blocked?'Geblokkeerd':($sub?ucfirst($sub->plan).' · '.$sub->status:($app?'Aanvraag · '.$app->status:'Makelaar'));$nonce=wp_create_nonce('rvaz_wonen_agent_'.$u->ID);
   $b.='<tr><td><strong>'.esc_html($u->display_name).'</strong><br><small>'.esc_html($u->user_email).'</small></td><td>'.esc_html($status).'</td><td>'.count_user_posts($u->ID,self::TYPE,true).'</td><td><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rvaz_wonen_agent_manage"><input type="hidden" name="user_id" value="'.$u->ID.'"><input type="hidden" name="nonce" value="'.$nonce.'"><input type="hidden" name="do" value="limit"><input style="width:65px" type="number" min="0" name="limit" value="'.esc_attr($limit).'"> <button class="button">Opslaan</button></form></td><td><a class="button" href="'.esc_url(admin_url('user-edit.php?user_id='.$u->ID)).'">Bewerken</a> <form style="display:inline" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="rvaz_wonen_agent_manage"><input type="hidden" name="user_id" value="'.$u->ID.'"><input type="hidden" name="nonce" value="'.$nonce.'"><button class="button" name="do" value="'.($blocked?'unblock':'block').'">'.($blocked?'Deblokkeren':'Blokkeren').'</button> <button class="button" name="do" value="remove_wonen" onclick="return confirm(\'Wonen-toegang verwijderen en woningen op concept zetten?\')">Wonen verwijderen</button></form></td></tr>';
  }$b.='</table>';self::admin_wrap('Makelaars',$b);
 }
 static function application_decision(){
  if(!current_user_can('manage_options'))wp_die('Niet toegestaan');global $wpdb;$id=absint($_GET['id']??0);
  if(!$id||!wp_verify_nonce($_GET['nonce']??'','rvaz_wonen_application_'.$id))wp_die('Niet toegestaan');
  $decision=sanitize_key($_GET['decision']??'');$row=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->prefix}rvaz_wonen_applications WHERE id=%d",$id));
  if(!$row||$row->status!=='pending'||!in_array($decision,['approve','reject'],true))wp_die('Ongeldige aanvraag');
  if($decision==='approve'){
   $user=new WP_User((int)$row->user_id);$user->add_role(self::ROLE);
   $wpdb->update($wpdb->prefix.'rvaz_wonen_applications',['status'=>'approved'],['id'=>$id]);
   $existing=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$wpdb->prefix}rvaz_wonen_subscriptions WHERE user_id=%d AND status='active' LIMIT 1",$row->user_id));
   if($existing)$wpdb->update($wpdb->prefix.'rvaz_wonen_subscriptions',['plan'=>$row->plan,'start_date'=>current_time('Y-m-d')],['id'=>$existing]);
   else $wpdb->insert($wpdb->prefix.'rvaz_wonen_subscriptions',['user_id'=>$row->user_id,'plan'=>$row->plan,'status'=>'active','start_date'=>current_time('Y-m-d'),'end_date'=>date('Y-m-d',strtotime(current_time('Y-m-d').' +1 month -1 day')),'next_invoice_date'=>date('Y-m-d',strtotime(current_time('Y-m-d').' +1 month'))]);
   update_user_meta($row->user_id,'rvaz_wonen_office_name',$row->office); self::create_invoice((int)$row->user_id,$row->plan);
  }else $wpdb->update($wpdb->prefix.'rvaz_wonen_applications',['status'=>'rejected'],['id'=>$id]);
  wp_safe_redirect(admin_url('admin.php?page=rvaz-wonen-aanvragen'));exit;
 }
